starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "domain_name" {
  description = "Input variable domain_name."
  type        = string
  default     = "example.com"
}

variable "record_name" {
  description = "Input variable record_name."
  type        = string
  default     = "app"
}

variable "project_name" {
  description = "Input variable project_name."
  type        = string
  default     = "terraform-practice"
}

variable "environment" {
  description = "Input variable environment."
  type        = string
  default     = "dev"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_route53_zone" "this" {
  name = "example.com"
}

resource "aws_acm_certificate" "this" {
  domain_name       = "example.com"
  validation_method = "DNS"
}

resource "aws_cloudfront_distribution" "this" {
  # TODO - Complete the aws_cloudfront_distribution resource.
  # Add the arguments and nested blocks required for aws_cloudfront_distribution.
}

resource "aws_route53_record" "this" {
  name    = "www.example.com"
  type    = "A"
  zone_id = aws_route53_zone.this.zone_id
  alias {
    name    = aws_cloudfront_distribution.this.domain_name
    zone_id = aws_cloudfront_distribution.this.hosted_zone_id
  }
}

starter.outputs.tf:
output "zone_id" {
  value = aws_route53_zone.this.zone_id
}

output "certificate_arn" {
  value = aws_acm_certificate.this.arn
}
